package com.campus.expense;
import java.time.*;import java.util.*;
public class Main {public static void main(String[] args){ExpenseService es=new ExpenseService(new FileExpenseRepository("data/expenses.csv"));BudgetService bs=new BudgetService(new BudgetRepository("data/budgets.csv"));AnalyticsService as=new AnalyticsService(es,bs);ConsoleHelper io=new ConsoleHelper(new Scanner(System.in));System.out.println("======================================\n       CAMPUS EXPENSE MANAGER\n======================================");boolean run=true;while(run){menu();int c=io.integer("Choose an option: ");try{switch(c){case 1->add(io,es);case 2->list(es);case 3->search(io,es);case 4->update(io,es);case 5->delete(io,es);case 6->budget(io,bs);case 7->System.out.println(as.budgetStatus(io.month()));case 8->analytics(io,as);case 0->run=false;default->System.out.println("Choose a listed option.");}}catch(IllegalArgumentException e){System.out.println("Error: "+e.getMessage());AppLogger.warn(e.getMessage());}catch(RuntimeException e){System.out.println("Unexpected error. Check data/app.log.");AppLogger.warn(e.toString());}System.out.println();}System.out.println("Thank you for using Campus Expense Manager.");}
 static void menu(){System.out.println("\n1. Add expense\n2. List expenses\n3. Search expenses\n4. Update expense\n5. Delete expense\n6. Set monthly budget\n7. View budget status\n8. View monthly analytics\n0. Exit");}
 static void add(ConsoleHelper i,ExpenseService s){Expense e=s.add(i.text("Description: "),i.amount("Amount: "),i.category(),i.date());System.out.println("Added: "+e);}static void list(ExpenseService s){var x=s.list();if(x.isEmpty())System.out.println("No expenses recorded.");else x.forEach(System.out::println);}static void search(ConsoleHelper i,ExpenseService s){var x=s.search(i.text("Search keyword/category: "));if(x.isEmpty())System.out.println("No matching expenses.");else x.forEach(System.out::println);}static void update(ConsoleHelper i,ExpenseService s){int id=i.integer("Expense ID: ");s.update(id,i.text("New description: "),i.amount("New amount: "),i.category(),i.date());System.out.println("Expense updated.");}static void delete(ConsoleHelper i,ExpenseService s){s.delete(i.integer("Expense ID: "));System.out.println("Expense deleted.");}static void budget(ConsoleHelper i,BudgetService s){s.setBudget(i.month(),i.amount("Monthly budget: "));System.out.println("Budget saved.");}static void analytics(ConsoleHelper i,AnalyticsService s){YearMonth m=i.month();System.out.printf("Total spending for %s: %.2f%n",m,s.totalForMonth(m));System.out.println("Category-wise spending:");var t=s.categoryTotals(m);if(t.isEmpty())System.out.println("No spending recorded.");else t.forEach((k,v)->System.out.printf("  %-15s %.2f%n",k,v));System.out.println(s.budgetStatus(m));}}
